const normalizeText = (value) => String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();
const cfgNode = $('Normalize Social Payload Remotion').first();
if (!cfgNode || !cfgNode.json) throw new Error('Missing Normalize Social Payload Remotion output');
const cfg = cfgNode.json;
const rows = items.map((i) => i.json || {}).filter((r) => {
  if (r.error) return false;
  const title = r.video_title || r.title || '';
  const hook = r.hook_line || r.hook || '';
  const targetPage = r.target_page || r.target_url || '';
  return Boolean(title || hook || targetPage);
});
const library = rows.slice(-500).map((r) => {
  const title = String(r.video_title || r.title || '').trim();
  const hook = String(r.hook_line || r.hook || '').trim();
  const target_page = String(r.target_page || r.target_url || '').trim();
  const status = String(r.status || '').trim();
  const notes = String(r.notes || '').trim();
  const dedupe_key = String(r.dedupe_key || '').trim() || [normalizeText(title), normalizeText(hook), normalizeText(target_page)].filter(Boolean).join(' | ');
  return { title, hook, dedupe_key, target_page, status, notes };
});
const plannerLibrary = library.filter((r) => r.status !== 'failed').slice(-80);
return [{ json: { ...cfg, existing_video_library: library, existing_video_library_text: JSON.stringify(plannerLibrary, null, 2), existing_video_count: library.length } }];

const raw = items[0]?.json || {};
let payload = raw.output ?? raw.response ?? raw.text ?? raw;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) {}
}
payload = payload.social_video_plan || payload;
const cfg = $('Build Existing Video Library').first().json;
const clean = (v) => String(v || '').replace(/\s+/g, ' ').trim();
const slugify = (v) => clean(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/--+/g, '-');
const clamp = (n, min, max) => Math.max(min, Math.min(max, Number(n || 0) || 0));
const words = (v) => clean(v).split(' ').filter(Boolean).length;
const normalizePlatforms = (value) => Array.isArray(value) && value.length ? value.map((entry) => String(entry)) : ['instagram_reels', 'facebook_reels', 'tiktok'];
let scenes = Array.isArray(payload.scene_plan) ? payload.scene_plan : [];
if (!scenes.length) throw new Error('No scenes were generated by the planner.');
scenes = scenes.slice(0, Number(cfg.max_total_scenes || 8)).map((scene, idx) => ({
  scene_index: idx + 1,
  role: ['hook', 'pain', 'solution', 'proof', 'offer', 'cta'].includes(String(scene.role || '').toLowerCase()) ? String(scene.role).toLowerCase() : (idx === 0 ? 'hook' : (idx === scenes.length - 1 ? 'cta' : 'solution')),
  headline: clean(scene.headline || ''),
  supporting_text: clean(scene.supporting_text || ''),
  narration: clean(scene.narration || ''),
  on_screen_text: clean(scene.on_screen_text || ''),
  preferred_source: String(scene.preferred_source || 'pexels').toLowerCase() === 'generated_image' ? 'generated_image' : 'pexels',
  asset_choice_reason: clean(scene.asset_choice_reason || ''),
  pexels_query: clean(scene.pexels_query || payload.video_title || cfg.acquisition_summary?.title_hint || 'healthcare training'),
  fallback_image_prompt: clean(scene.fallback_image_prompt || `Ultra-realistic vertical still for ${payload.video_title || cfg.acquisition_summary?.title_hint || 'ExcelCNA social video'}, no text, no logos`),
  asset_notes: clean(scene.asset_notes || ''),
  caption_text: clean(scene.caption_text || scene.narration || scene.on_screen_text),
  badge_label: clean(scene.badge_label || ''),
  badge_value: clean(scene.badge_value || ''),
  duration_seconds: Number(scene.duration_seconds || 0) || 0
})).filter((scene) => scene.narration || scene.on_screen_text || scene.headline);
if (!scenes.length) throw new Error('Planner output could not be converted into scenes.');
const openingHook = clean(payload.opening_hook || cfg.acquisition_summary?.hook_hint || cfg.acquisition_summary?.title_hint);
const ctaLine = clean(payload.cta_line || `Visit ${cfg.routing?.resolved_target_url || cfg.planner_context?.targetUrl} to get started.`);
let fullVoiceover = clean(payload.full_voiceover_script || '');
if (!fullVoiceover) fullVoiceover = [openingHook, ...scenes.map((scene) => scene.narration), ctaLine].filter(Boolean).join(' ');
if (openingHook && !fullVoiceover.toLowerCase().includes(openingHook.toLowerCase().slice(0, 18))) fullVoiceover = `${openingHook} ${fullVoiceover}`;
if (ctaLine && !fullVoiceover.toLowerCase().includes(ctaLine.toLowerCase().slice(0, 18))) fullVoiceover = `${fullVoiceover} ${ctaLine}`;
fullVoiceover = clean(fullVoiceover);
if (!fullVoiceover) throw new Error('Voiceover script is missing after parsing.');
const speechDuration = Math.ceil(words(fullVoiceover) / 2.45) + 4;
const requested = Number(cfg.planner_context?.requestedDurationSec || cfg.requested_duration_seconds || 0) || 0;
const plannerDuration = Number(payload.target_duration_seconds || 0) || 0;
let targetDuration = Math.max(requested || 0, plannerDuration || 0, speechDuration || 0, Number(cfg.min_duration_seconds || 50));
targetDuration = clamp(targetDuration, Number(cfg.min_duration_seconds || 50), Number(cfg.max_duration_seconds || 120));
const totalWeight = scenes.reduce((sum, scene) => sum + Math.max(words(scene.narration), 3), 0);
let assigned = 0;
scenes = scenes.map((scene) => {
  const weight = Math.max(words(scene.narration), 3);
  const planned = scene.duration_seconds > 0 ? scene.duration_seconds : Math.max(5, Math.round((weight / totalWeight) * targetDuration));
  assigned += planned;
  return { ...scene, duration_seconds: planned };
});
if (assigned !== targetDuration && scenes.length) {
  scenes[scenes.length - 1].duration_seconds = Math.max(5, scenes[scenes.length - 1].duration_seconds + (targetDuration - assigned));
}
const hashtags = Array.isArray(payload.hashtags) ? payload.hashtags.filter(Boolean).slice(0, 8).map((v) => String(v)) : ['#ExcelCNA'];
const videoTitle = clean(payload.video_title || cfg.acquisition_summary?.title_hint || 'ExcelCNA social video');
const targetUrl = clean(payload.target_url || cfg.routing?.resolved_target_url || cfg.planner_context?.targetUrl);
return [{ json: {
  ...cfg,
  video_title: videoTitle,
  slug: slugify(payload.slug || videoTitle || 'excelcna-social-video'),
  template_family: ['proof-driven', 'problem-solution', 'story/testimonial'].includes(payload.template_family) ? payload.template_family : (cfg.planner_context?.templateFamilyHint || 'proof-driven'),
  target_duration_seconds: targetDuration,
  platforms: normalizePlatforms(payload.platforms),
  target_url: targetUrl,
  voice_style: clean(payload.voice_style || 'warm, practical, credible, calm, adult'),
  opening_hook: openingHook,
  cta_line: ctaLine,
  full_voiceover_script: fullVoiceover,
  tts_input_text: fullVoiceover,
  caption: clean(payload.caption || `${openingHook} ${ctaLine}`),
  hashtags,
  why_this_angle: clean(payload.why_this_angle || ''),
  scene_plan: scenes,
  scene_count: scenes.length,
  dedupe_key: slugify(payload.dedupe_key || [videoTitle, openingHook, targetUrl].join(' | '))
}}];

const j = items[0].json;
const norm = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const titleNorm = norm(j.video_title);
const hookNorm = norm(j.opening_hook);
const keyNorm = norm(j.dedupe_key);
const targetNorm = norm(j.target_url);
const matches = (j.existing_video_library || []).filter((v) => {
  const vt = norm(v.title);
  const vh = norm(v.hook);
  const vk = norm(v.dedupe_key);
  const page = norm(v.target_page);
  return (vk && vk === keyNorm) || ((page && page === targetNorm) && ((vt && vt === titleNorm) || (vh && vh === hookNorm)));
});
return [{ json: { ...j, is_duplicate: matches.length > 0, duplicate_matches: matches.slice(0, 6) } }];

const j = items[0].json;
const prompt = `The first draft matched an existing video angle. You must create a materially different ExcelCNA social video plan for the same business goal.

Use these rules:
${j.social_skill_markdown}

ORIGINAL SOURCE PAYLOAD:
${JSON.stringify(j.source_payload, null, 2)}

FIRST DRAFT THAT MUST NOT BE REPEATED:
${JSON.stringify({ video_title: j.video_title, opening_hook: j.opening_hook, why_this_angle: j.why_this_angle, dedupe_key: j.dedupe_key }, null, 2)}

MATCHING EXISTING VIDEOS:
${JSON.stringify(j.duplicate_matches || [], null, 2)}

TASK:
Create a stronger alternative angle for the same business goal.
- Do not reuse the same title structure.
- Do not reuse the same hook structure.
- Do not reuse the same promise framing.
- Prefer a different narrative arc or self-qualification angle.
- Final duration must stay between ${j.planner_context.minDurationSec} and ${j.planner_context.maxDurationSec} seconds.
- Return only JSON matching the same schema.`;
return [{ json: { ...j, alternate_planning_prompt: prompt } }];

const raw = items[0]?.json || {};
let payload = raw.output ?? raw.response ?? raw.text ?? raw;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) {}
}
payload = payload.social_video_plan || payload;
const cfg = $('Prepare Alternate Social Plan Prompt').first().json;
const clean = (v) => String(v || '').replace(/\s+/g, ' ').trim();
const slugify = (v) => clean(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/--+/g, '-');
const clamp = (n, min, max) => Math.max(min, Math.min(max, Number(n || 0) || 0));
const words = (v) => clean(v).split(' ').filter(Boolean).length;
let scenes = Array.isArray(payload.scene_plan) ? payload.scene_plan : [];
if (!scenes.length) throw new Error('No alternate scenes were generated by the planner.');
scenes = scenes.slice(0, Number(cfg.max_total_scenes || 8)).map((scene, idx) => ({
  scene_index: idx + 1,
  role: ['hook', 'pain', 'solution', 'proof', 'offer', 'cta'].includes(String(scene.role || '').toLowerCase()) ? String(scene.role).toLowerCase() : (idx === 0 ? 'hook' : (idx === scenes.length - 1 ? 'cta' : 'solution')),
  headline: clean(scene.headline || ''),
  supporting_text: clean(scene.supporting_text || ''),
  narration: clean(scene.narration || ''),
  on_screen_text: clean(scene.on_screen_text || ''),
  preferred_source: String(scene.preferred_source || 'pexels').toLowerCase() === 'generated_image' ? 'generated_image' : 'pexels',
  asset_choice_reason: clean(scene.asset_choice_reason || ''),
  pexels_query: clean(scene.pexels_query || payload.video_title || cfg.acquisition_summary?.title_hint || 'healthcare training'),
  fallback_image_prompt: clean(scene.fallback_image_prompt || `Ultra-realistic vertical still for ${payload.video_title || cfg.acquisition_summary?.title_hint || 'ExcelCNA social video'}, no text, no logos`),
  asset_notes: clean(scene.asset_notes || ''),
  caption_text: clean(scene.caption_text || scene.narration || scene.on_screen_text),
  badge_label: clean(scene.badge_label || ''),
  badge_value: clean(scene.badge_value || ''),
  duration_seconds: Number(scene.duration_seconds || 0) || 0
})).filter((scene) => scene.narration || scene.on_screen_text || scene.headline);
const openingHook = clean(payload.opening_hook || cfg.acquisition_summary?.hook_hint || cfg.acquisition_summary?.title_hint);
const ctaLine = clean(payload.cta_line || `Visit ${cfg.routing?.resolved_target_url || cfg.planner_context?.targetUrl} to get started.`);
let fullVoiceover = clean(payload.full_voiceover_script || '');
if (!fullVoiceover) fullVoiceover = [openingHook, ...scenes.map((scene) => scene.narration), ctaLine].filter(Boolean).join(' ');
fullVoiceover = clean(fullVoiceover);
const speechDuration = Math.ceil(words(fullVoiceover) / 2.45) + 4;
let targetDuration = Math.max(Number(cfg.planner_context?.requestedDurationSec || cfg.requested_duration_seconds || 0), Number(payload.target_duration_seconds || 0), speechDuration || 0, Number(cfg.min_duration_seconds || 50));
targetDuration = clamp(targetDuration, Number(cfg.min_duration_seconds || 50), Number(cfg.max_duration_seconds || 120));
const totalWeight = scenes.reduce((sum, scene) => sum + Math.max(words(scene.narration), 3), 0);
let assigned = 0;
scenes = scenes.map((scene) => {
  const weight = Math.max(words(scene.narration), 3);
  const planned = scene.duration_seconds > 0 ? scene.duration_seconds : Math.max(5, Math.round((weight / totalWeight) * targetDuration));
  assigned += planned;
  return { ...scene, duration_seconds: planned };
});
if (assigned !== targetDuration && scenes.length) scenes[scenes.length - 1].duration_seconds = Math.max(5, scenes[scenes.length - 1].duration_seconds + (targetDuration - assigned));
return [{ json: {
  ...cfg,
  video_title: clean(payload.video_title || cfg.acquisition_summary?.title_hint || 'ExcelCNA social video'),
  slug: slugify(payload.slug || payload.video_title || cfg.acquisition_summary?.title_hint || 'excelcna-social-video'),
  template_family: ['proof-driven', 'problem-solution', 'story/testimonial'].includes(payload.template_family) ? payload.template_family : (cfg.planner_context?.templateFamilyHint || 'proof-driven'),
  target_duration_seconds: targetDuration,
  platforms: Array.isArray(payload.platforms) && payload.platforms.length ? payload.platforms : ['instagram_reels', 'facebook_reels', 'tiktok'],
  target_url: clean(payload.target_url || cfg.routing?.resolved_target_url || cfg.planner_context?.targetUrl),
  voice_style: clean(payload.voice_style || 'warm, practical, credible, calm, adult'),
  opening_hook: openingHook,
  cta_line: ctaLine,
  full_voiceover_script: fullVoiceover,
  tts_input_text: fullVoiceover,
  caption: clean(payload.caption || `${openingHook} ${ctaLine}`),
  hashtags: Array.isArray(payload.hashtags) && payload.hashtags.length ? payload.hashtags.filter(Boolean).slice(0, 8).map((v) => String(v)) : ['#ExcelCNA'],
  why_this_angle: clean(payload.why_this_angle || ''),
  scene_plan: scenes,
  scene_count: scenes.length,
  dedupe_key: slugify(payload.dedupe_key || [payload.video_title || cfg.acquisition_summary?.title_hint, openingHook, cfg.routing?.resolved_target_url].join(' | ')),
  replanned_from_duplicate: true
}}];

const j = items[0].json;
const norm = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const titleNorm = norm(j.video_title);
const hookNorm = norm(j.opening_hook);
const keyNorm = norm(j.dedupe_key);
const targetNorm = norm(j.target_url);
const matches = (j.existing_video_library || []).filter((v) => {
  const vt = norm(v.title);
  const vh = norm(v.hook);
  const vk = norm(v.dedupe_key);
  const page = norm(v.target_page);
  return (vk && vk === keyNorm) || ((page && page === targetNorm) && ((vt && vt === titleNorm) || (vh && vh === hookNorm)));
});
return [{ json: { ...j, is_duplicate: matches.length > 0, duplicate_matches: matches.slice(0, 6) } }];

const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const scene = $('Create Scene Items').itemMatching(i).json;
  const photos = Array.isArray(resp.photos) ? resp.photos : [];
  const first = photos.map((photo) => ({
    imageUrl: photo?.src?.large2x || photo?.src?.large || photo?.src?.original || '',
    photoPage: photo?.url || '',
    photographer: photo?.photographer || ''
  })).find((photo) => photo.imageUrl) || null;
  const pexelsImageUrl = first?.imageUrl || '';
  out.push({
    json: {
      ...scene,
      pexels_found: !!pexelsImageUrl,
      pexels_image_url: pexelsImageUrl,
      pexels_credit: pexelsImageUrl ? {
        type: 'pexels',
        photo_page: first.photoPage,
        photographer: first.photographer,
        query: scene.pexels_query,
        reason: scene.asset_choice_reason || ''
      } : null,
      needs_generated_image: scene.preferred_source === 'generated_image' || !pexelsImageUrl
    },
    pairedItem: i
  });
}
return out;

const scenes = items.map((i) => i.json.scene_payload || i.json || {}).filter((s) => s.scene_asset_url).sort((a, b) => Number(a.scene_index || 0) - Number(b.scene_index || 0));
const plan = $('Create Scene Items').first().json;
if (!plan.tts_input_text) throw new Error('Voiceover script is missing before TTS generation.');
if (!scenes.length) throw new Error('No scenes were assembled.');
const missingAsset = scenes.find((scene) => !scene.scene_asset_url);
if (missingAsset) throw new Error(`Required asset URL missing for scene ${missingAsset.scene_index}.`);
const credits = scenes.map((scene) => { try { return JSON.parse(scene.asset_credit_json || '{}'); } catch (e) { return {}; } });
const generatedCount = credits.filter((credit) => credit.type === 'generated').length;
return [{ json: {
  ...plan,
  generated_scene_count: generatedCount,
  pexels_scene_count: scenes.length - generatedCount,
  scenes,
  asset_credits_json: JSON.stringify(credits)
}}];

const j = items[0].json;
if (!j.tts_input_text) throw new Error('Voiceover script is missing.');
const ttsInstructions = `Read this like a calm, trustworthy, practical adult guide. Keep the delivery warm and human, not salesy, not robotic, and not overexcited. End with a grounded call to action.`;
const body = {
  model: j.tts_model || 'gpt-4o-mini-tts',
  input: j.tts_input_text,
  voice: j.tts_voice || 'ash',
  instructions: ttsInstructions,
  response_format: 'mp3',
  speed: Number(j.tts_speed || 0.96)
};
return [{ json: { ...j, tts_request_body: body, voiceover_object_name: `social-videos/${j.slug}/voiceover.mp3`, voiceover_public_url: `${j.gcs_base_url}/${j.bucket_name}/social-videos/${j.slug}/voiceover.mp3` } }];

const base = $('Prepare TTS Request').first().json;
const voice = $('Set Voiceover URL').first().json.voiceover_url;
if (!Array.isArray(base.scenes) || !base.scenes.length) throw new Error('No scenes found for Remotion package assembly.');
if (!voice) throw new Error('Voiceover URL missing before Remotion package assembly.');
const brand = base.planner_context.brandSeed || {};
const remotionPayload = {
  adId: base.planner_context.adId,
  campaignId: base.planner_context.campaignId,
  templateFamily: base.template_family,
  brandName: brand.brandName || 'ExcelCNA',
  ctaLabel: base.cta_line || 'Learn more',
  ctaUrl: base.target_url,
  trackingSlug: base.slug,
  aspectRatio: '9:16',
  logoUrl: brand.logoUrl || 'https://placehold.co/512x512/png?text=ExcelCNA',
  primaryColor: brand.primaryColor || '#0E7490',
  secondaryColor: brand.secondaryColor || '#F59E0B',
  textColor: brand.textColor || '#F8FAFC',
  accentColor: brand.accentColor || '#FDE68A',
  surfaceColor: brand.surfaceColor || '#08101F',
  voiceoverUrl: voice,
  targetDurationSec: Number(base.target_duration_seconds || 60),
  scenes: base.scenes.map((scene) => ({
    id: `scene-${String(scene.scene_index).padStart(2, '0')}`,
    role: scene.role,
    headline: scene.headline || scene.on_screen_text || '',
    supportingText: scene.supporting_text || '',
    badgeLabel: scene.badge_label || undefined,
    badgeValue: scene.badge_value || undefined,
    mediaUrl: scene.scene_asset_url,
    mediaType: 'image',
    captionText: scene.caption_text || scene.narration || scene.on_screen_text || ''
  })),
  captions: {
    phrases: base.scenes.map((scene) => ({
      sceneId: `scene-${String(scene.scene_index).padStart(2, '0')}`,
      text: scene.caption_text || scene.narration || scene.on_screen_text || ''
    })).filter((entry) => entry.text)
  }
};
const renderRequest = {
  compositionId: 'SocialAd',
  payload: remotionPayload,
  slug: base.slug,
  outputObjectName: `social-videos/${base.slug}/render.mp4`
};
return [{ json: {
  ...base,
  voiceover_url: voice,
  remotion_payload: remotionPayload,
  remotion_payload_json: JSON.stringify(remotionPayload),
  remotion_render_request: renderRequest
}}];

const row = items[0].json || {};
const base = $('Build Remotion Render Package').first().json;
return [{ json: { ...row, result: row.status, remotion_payload: base.remotion_payload, remotion_render_request: base.remotion_render_request, voiceover_url: base.voiceover_url, remotion_payload_json: base.remotion_payload_json } }];
